#!/usr/bin/env node
var identifier,argv=process.argv.slice(2),versions=[],range=[],inc=null,version=require("../package.json").version,loose=!1,includePrerelease=!1,coerce=!1,rtl=!1,semver=require("../semver"),reverse=!1,options={};function main(){if(!argv.length)return help();for(;argv.length;){var e=argv.shift(),r=e.indexOf("=");switch(-1!==r&&(e=e.slice(0,r),argv.unshift(e.slice(r+1))),e){case"-rv":case"-rev":case"--rev":case"--reverse":reverse=!0;break;case"-l":case"--loose":loose=!0;break;case"-p":case"--include-prerelease":includePrerelease=!0;break;case"-v":case"--version":versions.push(argv.shift());break;case"-i":case"--inc":case"--increment":switch(argv[0]){case"major":case"minor":case"patch":case"prerelease":case"premajor":case"preminor":case"prepatch":inc=argv.shift();break;default:inc="patch"}break;case"--preid":identifier=argv.shift();break;case"-r":case"--range":range.push(argv.shift());break;case"-c":case"--coerce":coerce=!0;break;case"--rtl":rtl=!0;break;case"--ltr":rtl=!1;break;case"-h":case"--help":case"-?":return help();default:versions.push(e)}}var s={loose:loose,includePrerelease:includePrerelease,rtl:rtl};if(!(versions=versions.map(function(e){return coerce?(semver.coerce(e,s)||{version:e}).version:e}).filter(function(e){return semver.valid(e)})).length)return fail();if(inc&&(1!==versions.length||range.length))return failInc();for(var n=0,i=range.length;n<i;n++)if(!(versions=versions.filter(function(e){return semver.satisfies(e,range[n],s)})).length)return fail();return success(versions)}function failInc(){console.error("--inc can only be used on a single version with no range"),fail()}function fail(){process.exit(1)}function success(){var e=reverse?"rcompare":"compare";versions.sort(function(r,s){return semver[e](r,s,options)}).map(function(e){return semver.clean(e,options)}).map(function(e){return inc?semver.inc(e,inc,options,identifier):e}).forEach(function(e,r,s){console.log(e)})}function help(){console.log(["SemVer "+version,"","A JavaScript implementation of the https://semver.org/ specification","Copyright Isaac Z. Schlueter","","Usage: semver [options] <version> [<version> [...]]","Prints valid versions sorted by SemVer precedence","","Options:","-r --range <range>","        Print versions that match the specified range.","","-i --increment [<level>]","        Increment a version by the specified level.  Level can","        be one of: major, minor, patch, premajor, preminor,","        prepatch, or prerelease.  Default level is 'patch'.","        Only one version may be specified.","","--preid <identifier>","        Identifier to be used to prefix premajor, preminor,","        prepatch or prerelease version increments.","","-l --loose","        Interpret versions and ranges loosely","","-p --include-prerelease","        Always include prerelease versions in range matching","","-c --coerce","        Coerce a string into SemVer if possible","        (does not imply --loose)","","--rtl","        Coerce version strings right to left","","--ltr","        Coerce version strings left to right (default)","","Program exits successfully if any valid version satisfies","all supplied ranges, and prints all satisfying versions.","","If no satisfying versions are found, then exits failure.","","Versions are printed in ascending order, so supplying","multiple versions to the utility will just sort them."].join("\n"))}main();